import {suite,VERSION,evaluate,parseResponses} from './engine.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let answers={},result=null,isDemo=false,filter='All',runs=[],storageOK=true;
try {const saved=JSON.parse(localStorage.getItem('verity-runs-v1')||'[]');if(Array.isArray(saved))runs=saved.filter(r=>r&&r.suiteVersion===VERSION&&typeof r.id==='string'&&typeof r.model==='string'&&typeof r.date==='string'&&r.answers&&typeof r.answers==='object'&&!Array.isArray(r.answers)&&Object.values(r.answers).every(v=>typeof v==='string')).slice(0,30).map(r=>({...r,...evaluate(r.answers)}));}catch{storageOK=false;}
function toast(message){$('#toast').textContent=message;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').textContent='',4500);}
function download(name,data,type='application/json'){const url=URL.createObjectURL(new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function invalidate(){result=null;$('#empty-results').hidden=false;$('#results-content').hidden=true;$('#result-state').textContent='READY WHEN YOU ARE';$('#result-state').className='tag neutral';$$('.case .badge').forEach(b=>{b.textContent='Not evaluated';b.className='badge'});$$('.evidence').forEach(e=>e.remove());$('#input-error').textContent='';}
function renderCases(){
 const openIds=new Set($$('.case[open]').map(el=>el.dataset.id));
 $('#case-list').innerHTML=suite.filter(t=>filter==='All'||t.category===filter).map(t=>{const row=result?.rows.find(r=>r.id===t.id);return `<details class="case" data-id="${t.id}" ${openIds.has(t.id)?'open':''}><summary><span class="case-id">${t.id}</span><span class="case-title">${t.title}</span><span class="category-label">${t.category}</span><span class="badge ${row?.status||''}">${row?label(row.status):'Not evaluated'}</span></summary><div class="case-body"><p class="prompt">${escape(t.prompt)}</p><button class="text-button copy" data-id="${t.id}">Copy prompt ↗</button><label for="answer-${t.id}">Model response</label><textarea id="answer-${t.id}" data-id="${t.id}" maxlength="20000" placeholder="Paste your model’s answer here…">${escape(answers[t.id]||'')}</textarea>${row?`<div class="evidence"><b>Expected:</b> <code>${escape(t.expected)}</code><p>${escape(t.evidence)}</p><p>${escape(row.reason)}</p></div>`:''}</div></details>`}).join('');
 $$('.case textarea').forEach(el=>el.addEventListener('input',()=>{answers[el.dataset.id]=el.value;invalidate()}));
 $$('.copy').forEach(el=>el.onclick=async()=>{try{await navigator.clipboard.writeText(suite.find(t=>t.id===el.dataset.id).prompt);toast('Prompt copied. Run it in a fresh conversation.')}catch{toast('Clipboard is unavailable. Select and copy the prompt text.')}});
}
function label(status){return {pass:'Passed',flag:'Flagged',review:'Review',missing:'Missing'}[status]}
function pct(n,d){return d?Math.round(100*n/d)+'%':'—'}
function metrics(r){return `<div class="metric-grid">${['pass','flag','review','missing'].map(s=>`<div class="${s}"><strong>${r.counts[s]}</strong><span>${label(s)}</span></div>`).join('')}</div>`}
function renderResult(){
 $('#empty-results').hidden=true;$('#results-content').hidden=false;$('#result-state').textContent=isDemo?'ILLUSTRATIVE EXAMPLE':'EVALUATION COMPLETE';$('#result-state').className='tag '+(isDemo?'demo-label':'');
 $('#results-content').innerHTML=`<div class="results-heading">${escape(result.model)}</div><div class="agreement"><strong>${pct(result.counts.pass,result.graded)}</strong><span>agreement on graded answers</span></div><div class="coverage">Coverage: ${result.graded} / ${result.total} checks graded (${pct(result.graded,result.total)}). ${result.counts.review+result.counts.missing} unresolved.</div>${metrics(result)}<div>${['Grounding','Abstention','Reasoning','Faithfulness'].map(c=>{const p=result.rows.filter(r=>r.category===c&&r.status==='pass').length;return `<div class="dimension"><span>${c}</span><div class="bar"><i style="width:${p/3*100}%"></i></div><b>${p}/3</b></div>`}).join('')}</div><p class="fine">Bars show passes out of all three cases per dimension.</p><div class="note">${isDemo?'<b>Example data:</b> these answers are handcrafted to demonstrate different outcomes. No real model was tested.':'<b>Scope:</b> this small sample measures answer agreement. It is not a model-wide hallucination rate or a release certification.'}</div><div class="result-actions"><button id="save" class="button primary">Save run on this device</button><button id="export" class="button secondary">↓ Export report</button></div>`;
 $('#save').onclick=saveRun;$('#export').onclick=()=>exportRun(result);
}
function exportRun(r){download('verity-report-'+r.id+'.json',{...r,method:'Full-answer comparison, case-insensitive, outer whitespace trimmed.',limitations:'Small starter suite. Agreement is not a model-wide hallucination rate. Review and missing cases are unresolved.',exampleData:!!r.isDemo});}
function persist(){try{localStorage.setItem('verity-runs-v1',JSON.stringify(runs.map(({id,date,model,answers,isDemo,suiteVersion})=>({id,date,model,answers,isDemo,suiteVersion}))));return true}catch{toast('Could not save in this browser. Export your report instead.');return false}}
function saveRun(){if(!result)return;if(runs.some(r=>r.id===result.id)){toast('This run is already saved.');return}if(runs.length>=30){toast('Your 30-run limit is reached. Export and delete an older run first.');return}runs.unshift(structuredClone(result));if(!persist()){runs.shift();return}$('#run-count').textContent=runs.length;$('#save').textContent='Saved on this device ✓';toast('Run saved on this device, including the responses.');}
function renderReports(){
 $('#run-count').textContent=runs.length;
 if(!runs.length){$('#saved-list').innerHTML=`<div class="panel saved-empty"><div class="empty-symbol">▤</div><h3>Your next baseline starts here.</h3><p class="muted">Run an evaluation and save it to compare your builds.</p><a class="button primary" href="#workspace">Start an evaluation ↗</a></div>`;return}
 $('#saved-list').innerHTML=(runs.length>=2?`<div class="compare"><h2>Compare two builds</h2><div class="compare-controls"><div><label for="baseline">Baseline</label><select id="baseline">${runs.map((r,i)=>`<option value="${escape(r.id)}" ${i===1?'selected':''}>${escape(r.model)}${r.isDemo?' · example':''} · ${escape(new Date(r.date).toLocaleString())}</option>`).join('')}</select></div><div><label for="candidate">Candidate</label><select id="candidate">${runs.map(r=>`<option value="${escape(r.id)}">${escape(r.model)}${r.isDemo?' · example':''} · ${escape(new Date(r.date).toLocaleString())}</option>`).join('')}</select></div></div><div id="comparison"></div></div>`:'')+runs.map(r=>`<article class="panel run-card"><h2>${escape(r.model)} ${r.isDemo?'<span class="tag demo-label">EXAMPLE</span>':''}</h2><p class="run-meta">${escape(new Date(r.date).toLocaleString())} · ${VERSION} · ${r.graded}/12 graded</p>${metrics(r)}<div class="button-row"><button class="button secondary run-export" data-id="${escape(r.id)}">↓ Export report</button><button class="button secondary run-load" data-id="${escape(r.id)}">Inspect answers</button><button class="text-button run-delete" data-id="${escape(r.id)}">Delete run</button></div></article>`).join('');
 $$('.run-export').forEach(b=>b.onclick=()=>exportRun(runs.find(r=>r.id===b.dataset.id)));
 $$('.run-load').forEach(b=>b.onclick=()=>{result=structuredClone(runs.find(r=>r.id===b.dataset.id));answers={...result.answers};isDemo=!!result.isDemo;$('#model').value=result.model;filter='All';setFilter();renderCases();renderResult();location.hash='workspace';toast('Saved run loaded. Editing an answer clears its evaluation.');});
 $$('.run-delete').forEach(b=>b.onclick=()=>{if(!confirm('Delete this saved run from this browser? Export it first if you need a copy.'))return;const old=runs;runs=runs.filter(r=>r.id!==b.dataset.id);if(!persist()){runs=old;return}renderReports();toast('Run deleted.')});
 if(runs.length>=2){$('#baseline').onchange=compare;$('#candidate').onchange=compare;compare();}
}
function compare(){const a=runs.find(r=>r.id===$('#baseline').value),b=runs.find(r=>r.id===$('#candidate').value);if(a.id===b.id){$('#comparison').innerHTML='<p class="muted">Choose two different runs to compare.</p>';return}const common=a.rows.filter((r,i)=>['pass','flag'].includes(r.status)&&['pass','flag'].includes(b.rows[i].status));const ap=common.filter(r=>r.status==='pass').length,bp=common.filter(r=>b.rows.find(x=>x.id===r.id).status==='pass').length;const diff=common.length?Math.round((bp-ap)/common.length*100):null;$('#comparison').innerHTML=`<div class="compare-summary">${diff===null?'No mutually graded checks.':`Candidate agreement: <b>${diff>0?'+':''}${diff} percentage points</b> on ${common.length} mutually graded checks.`} ${(a.isDemo||b.isDemo)?'<b>Includes example data.</b>':''}</div><p class="fine">Only cases graded in both runs are compared. These small-sample differences do not establish statistical significance.</p><table class="comparison-table"><thead><tr><th>Outcome</th><th>Baseline</th><th>Candidate</th></tr></thead><tbody>${['pass','flag','review','missing'].map(s=>`<tr><td>${label(s)}</td><td>${a.counts[s]}</td><td>${b.counts[s]}</td></tr>`).join('')}</tbody></table>`}
function setFilter(){$$('.filters button').forEach(b=>{b.classList.toggle('active',b.dataset.filter===filter);b.setAttribute('aria-pressed',String(b.dataset.filter===filter))});}
$$('.filters button').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;setFilter();renderCases()});
$('#model').oninput=invalidate;
$('#evaluate').onclick=()=>{if(!Object.values(answers).some(x=>x.trim())){$('#input-error').textContent='Add at least one answer, import responses, or load the example to begin.';return}const model=$('#model').value.trim();if(!model){$('#input-error').textContent='Give this model or build a name first.';$('#model').focus();return}result={...evaluate(answers),id:crypto.randomUUID(),date:new Date().toISOString(),model,answers:{...answers},isDemo};$('#input-error').textContent='';renderCases();renderResult();toast('Evaluation complete. Open each check to inspect its evidence.');};
$('#demo').onclick=()=>{if(Object.values(answers).some(x=>x.trim())&&!confirm('Replace the current answers with illustrative example data?'))return;answers={G01:'2031',G02:'75',G03:'NO',A01:'Dr. Mira Chen',A02:'10.1234/imaginary.2032',A03:'UNKNOWN',R01:'408',R02:'YES',R03:'YES',F01:'June',F02:'The record lists 8 seats.',F03:'12'};isDemo=true;$('#model').value='Example agent · illustrative answers';invalidate();renderCases();toast('Example loaded. Select Run evaluation to see the results.');};
$('#clear').onclick=()=>{if(Object.values(answers).some(x=>x.trim())&&!confirm('Clear all current answers? Saved runs will remain.'))return;answers={};isDemo=false;invalidate();renderCases();toast('Answers cleared.');};
$('#prompts').onclick=()=>download('verity-prompts-v1.json',{suiteVersion:VERSION,instructions:'Run each prompt independently in a fresh conversation using the same model settings. Return model outputs verbatim; do not include reference answers in the model input.',tests:suite.map(({id,category,prompt})=>({id,category,prompt}))});
$('#template').onclick=()=>download('verity-responses-template.json',{suiteVersion:VERSION,model:'your-model-version',responses:Object.fromEntries(suite.map(t=>[t.id,'']))});
$('#import').onclick=()=>$('#file').click();
$('#file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>500000)throw Error('Use a JSON response file smaller than 500 KB.');const data=parseResponses(await file.text());if(Object.values(answers).some(x=>x.trim())&&!confirm('Replace the current answers with this file?'))return;answers={...data.answers};$('#model').value=data.model;isDemo=false;invalidate();renderCases();toast('Responses imported. Select Run evaluation.')}catch(error){$('#input-error').textContent=error.message}finally{e.target.value=''}};
function route(){const name=['workspace','reports','method'].includes(location.hash.slice(1))?location.hash.slice(1):'workspace';$$('.view').forEach(v=>v.hidden=v.id!==name);$$('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===name);if(a.dataset.nav===name)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});$('#crumb').textContent={workspace:'Evaluation lab',reports:'Saved runs',method:'Methodology'}[name];if(name==='reports')renderReports();window.scrollTo(0,0)}
window.addEventListener('hashchange',route);$('#run-count').textContent=runs.length;renderCases();route();if(!storageOK)toast('Browser storage is unavailable or unreadable. Reports can still be exported.');
